output_text:
[
  {
    "id": "must_take_cart_first",
    "text": "A shopper is obliged to take the available cart before doing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "at_cart_bay": "at(1,5)",
        "cart_available_at_bay": "cartAt(1,5)",
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "take_cart_from_bay": {
          "pre": {
            "and": [
              "PICKUP_CART",
              "at_cart_bay",
              "cart_available_at_bay"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_cart_from_bay"
    }
  },
  {
    "id": "no_hand_item_pickup",
    "text": "Items may not be picked up by hand; every item pickup must be done while the shopper has the cart.",
    "abstraction": {
      "state_properties": {
        "cartless": {
          "not": "hasCart"
        },
        "carrying_by_hand": "handFull"
      },
      "events": {
        "hand_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "cartless"
            ]
          },
          "post": null
        },
        "cart_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "hasCart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "hand_pickup"
    }
  },
  {
    "id": "return_cart_after_use",
    "text": "Once a shopper has used a cart, they are obliged to return it to the designated cart-return point before leaving.",
    "abstraction": {
      "state_properties": {
        "cart_return_point": "at(0,1)",
        "cart_parked_at_return": "cartAt(0,1)"
      },
      "events": {
        "take_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_at_point": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "cart_return_point"
            ]
          },
          "post": "cart_parked_at_return"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_at_point"
    }
  },
  {
    "id": "only_leave_cart_at_return",
    "text": "A cart may only be left at the designated cart-return cell.",
    "abstraction": {
      "state_properties": {
        "cart_return_point": "at(0,1)",
        "away_from_cart_return": {
          "not": "cart_return_point"
        }
      },
      "events": {
        "leave_cart_elsewhere": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "away_from_cart_return"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_elsewhere"
    }
  },
  {
    "id": "no_carts_in_exit_corridor",
    "text": "Carts are prohibited in the bottom exit corridor, so the shopper must abandon the cart before walking to the exit.",
    "abstraction": {
      "state_properties": {
        "exit_corridor": {
          "or": [
            "at(2,5)",
            "at(3,5)",
            "at(4,5)",
            "at(5,5)",
            "at(6,5)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "cart_in_exit_corridor": {
          "and": [
            "hasCart",
            "exit_corridor"
          ]
        }
      },
      "events": {
        "enter_exit_corridor_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "exit_corridor"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_exit_corridor"
    }
  },
  {
    "id": "no_south_with_cart_from_product_aisle",
    "text": "A shopper pushing a cart may not move south out of the upper product aisle.",
    "abstraction": {
      "state_properties": {
        "upper_product_aisle": {
          "or": [
            "at(2,2)",
            "at(3,2)",
            "at(4,2)",
            "at(5,2)",
            "at(6,2)"
          ]
        },
        "with_cart_in_product_aisle": {
          "and": [
            "hasCart",
            "upper_product_aisle"
          ]
        }
      },
      "events": {
        "south_with_cart_from_product_aisle": {
          "pre": {
            "and": [
              "with_cart_in_product_aisle",
              "S"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "south_with_cart_from_product_aisle"
    }
  },
  {
    "id": "return_to_entrance_after_cart_return",
    "text": "After returning the cart at the upper-left cart return, the shopper is obliged to walk back to the entrance-side aisle before exiting.",
    "abstraction": {
      "state_properties": {
        "cart_return_point": "at(0,1)",
        "cart_parked_at_return": "cartAt(0,1)",
        "entrance_side_cell": "at(0,5)"
      },
      "events": {
        "return_cart_at_point": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "cart_return_point"
            ]
          },
          "post": "cart_parked_at_return"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "return_cart_at_point",
      "discharge": "entrance_side_cell"
    }
  },
  {
    "id": "exit_only_after_cart_returned",
    "text": "The shopper may exit only when cartless and with the cart already parked at the return point.",
    "abstraction": {
      "state_properties": {
        "exit_cell": "at(9,5)",
        "cart_parked_at_return": "cartAt(0,1)",
        "cartless": {
          "not": "hasCart"
        },
        "empty_handed": {
          "not": "handFull"
        },
        "ready_to_exit": {
          "and": [
            "exit_cell",
            "cart_parked_at_return",
            "cartless",
            "empty_handed"
          ]
        }
      },
      "events": {
        "improper_exit": {
          "pre": {
            "and": [
              "EXIT",
              {
                "not": "ready_to_exit"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "improper_exit"
    }
  }
]
